
(function(){
  var EMBEDDED_TEMPLATE_B64='';
  var TEMPLATE_STORE='tcp_sales_meeting_template_b64_v2';
  var TEMPLATE_NAME_STORE='tcp_sales_meeting_template_name_v2';
  var CONFIG_STORE='tcp_sales_meeting_config_v1';
  var customImages={};
  function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function xmlEsc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');}
  function money(v){v=Number(v||0);return '$'+Math.round(v).toLocaleString();}
  function pct(a,b){return b>0?Math.round((Number(a||0)/Number(b||0))*100):0;}
  function allWeeks(){var rows=[];try{YEARS.forEach(function(y){QTRS.forEach(function(q){(gwq(y,q)||[]).forEach(function(w){var o=Object.assign({},w);o.year=y;o.q=q;rows.push(o);});});});}catch(e){}return rows;}
  function selectedPresentationWeek(){var y=parseInt((document.getElementById('smYear')||{}).value||getYr(),10);var q=(document.getElementById('smQuarter')||{}).value||getQ();var n=parseInt((document.getElementById('smWeek')||{}).value||getWN(),10);var w=(gwq(y,q)||[]).filter(function(x){return Number(x.num)===Number(n);})[0]||{num:n,label:'Wk '+n,key:y+'_'+q+'_'+n,start:new Date(),end:new Date()};w=Object.assign({},w);w.year=y;w.q=q;return w;}
  function previousWeekFor(w){var rows=allWeeks();var idx=rows.findIndex(function(x){return x.key===w.key;});if(idx>0)return rows[idx-1];return w;}
  function setStatus(msg,color){var el=document.getElementById('smStatus');if(el){el.textContent=msg||'';el.style.color=color||'#AEB8D6';}}
  function saveConfig(){try{var cfg={year:(document.getElementById('smYear')||{}).value,quarter:(document.getElementById('smQuarter')||{}).value,week:(document.getElementById('smWeek')||{}).value,summary:(document.getElementById('smSummaryText')||{}).value,custom:[]};for(var i=1;i<=3;i++){cfg.custom.push({title:(document.getElementById('smCustomTitle'+i)||{}).value||'',text:(document.getElementById('smCustomText'+i)||{}).value||''});}localStorage.setItem(CONFIG_STORE,JSON.stringify(cfg));}catch(e){}}
  function loadConfig(){try{return JSON.parse(localStorage.getItem(CONFIG_STORE)||'{}')||{};}catch(e){return {};}}
  function populateWeeks(){var y=parseInt((document.getElementById('smYear')||{}).value||getYr(),10);var q=(document.getElementById('smQuarter')||{}).value||getQ();var wk=document.getElementById('smWeek');if(!wk)return;var old=wk.value;var weeks=gwq(y,q)||[];wk.innerHTML=weeks.map(function(w){return '<option value="'+w.num+'">'+esc(w.label||('Wk '+w.num))+'</option>';}).join('');if(old&&weeks.some(function(w){return String(w.num)===String(old);}))wk.value=old;else wk.value=String(getWN&&getQ&&getYr&&y===getYr()&&q===getQ()?getWN():(weeks.length?weeks[weeks.length-1].num:''));}
  function templateName(){try{return localStorage.getItem(TEMPLATE_NAME_STORE)||'Built-in Sales Meeting template';}catch(e){return 'Built-in Sales Meeting template';}}
  function templateB64(){try{return localStorage.getItem(TEMPLATE_STORE)||EMBEDDED_TEMPLATE_B64;}catch(e){return EMBEDDED_TEMPLATE_B64;}}

  function smStart(w){var d=new Date(w&&w.start?w.start:new Date());d.setHours(0,0,0,0);return d;}
  function smEnd(w){var d=new Date(w&&w.end?w.end:new Date());d.setHours(23,59,59,999);return d;}
  function smDateOnly(d){var x=new Date(d);x.setHours(0,0,0,0);return x;}
  function smDateInWeek(dateISO,w){if(!dateISO||!w)return false;var d=smDateOnly(String(dateISO).indexOf('T')>=0?new Date(dateISO):new Date(String(dateISO)+'T12:00:00'));return d>=smStart(w)&&d<=smEnd(w);}
  function smPositiveRows(rows){return (rows||[]).filter(function(r){return Number(r.revenue||0)>0;});}
  function smSourceLabel(src){return src==='weekly'?'Weekly sales entry':src==='dailyRep'?'Per-rep daily SMB entries':src==='dailyTeam'?'Daily running totals':'No prior-week sales data';}
  function smWeeklyRows(reps,w){return reps.map(function(r){var d=(typeof gd==='function'?gd(r.name+'|'+w.key):{})||{};return {name:r.name,revenue:Number(d.revenue||0),calls:Number(d.calls||0),orders:Number(d.orders||0),source:'weekly'};}).sort(function(a,b){return b.revenue-a.revenue||a.name.localeCompare(b.name);});}
  function smDailyTeam(w){var daily={smb:0,corp:0,total:0,bestDay:null,days:0};try{var ds=(typeof getDailySales==='function'?getDailySales():[]);ds.forEach(function(e){if(smDateInWeek(e.date,w)){var total=Number(e.dailySales||0),smb=Number(e.smbSales||0),corp=Number(e.corpSales||0);daily.smb+=smb;daily.corp+=corp;daily.total+=total;daily.days++;if(!daily.bestDay||total>Number(daily.bestDay.dailySales||0))daily.bestDay=e;}});}catch(e){}return daily;}
  function smDailyRepRows(reps,w){var out=reps.map(function(r){return {name:r.name,revenue:0,calls:0,orders:0,source:'dailyRep'};});try{if(typeof _drEnsure==='function')_drEnsure();var by={};out.forEach(function(r){by[r.name]=r;});Object.keys(S.dailyRep||{}).filter(function(d){return /^\d{4}-\d{2}-\d{2}$/.test(d)&&smDateInWeek(d,w);}).sort().forEach(function(d){reps.forEach(function(r){var val=0;try{val=typeof _drRepDay==='function'?Number(_drRepDay(d,r.name)||0):0;}catch(e){val=0;}if(!val){var cur=Number((S.dailyRep[d]||{})[r.name]||0);var pd=(typeof _drPrevDate==='function'?_drPrevDate(d):null);var prev=pd?Number((S.dailyRep[pd]||{})[r.name]||0):0;val=Math.max(0,cur-prev);}by[r.name].revenue+=val;});});}catch(e){}return out.sort(function(a,b){return b.revenue-a.revenue||a.name.localeCompare(b.name);});}
  function smClip(s,n){s=String(s||'').replace(/\s+/g,' ').trim();n=n||150;return s.length>n?s.slice(0,n-1).replace(/\s+\S*$/,'')+'…':s;}
  function smReviewData(w){var reviews=[];try{if(typeof _rvActive==='function'&&typeof _rvEnriched==='function'&&typeof _rvInTrackerRange==='function'){reviews=_rvActive(_rvEnriched()).filter(function(x){return _rvInTrackerRange(x,w);});}}catch(e){reviews=[];}
    reviews=(reviews||[]).sort(function(a,b){var ad=a.date?+a.date:0,bd=b.date?+b.date:0;return bd-ad;});
    var paying=reviews.filter(function(r){try{return _rvPays(r.platform)&&(r.repName||r.rep);}catch(e){return r.repName||r.rep;}});
    var revMap={};paying.forEach(function(r){var k=r.repName||r.rep||'Unmatched';if(!revMap[k])revMap[k]=0;revMap[k]++;});
    var reviewRows=Object.keys(revMap).map(function(n){return {name:n,count:revMap[n],amount:revMap[n]*10};}).sort(function(a,b){return b.count-a.count||a.name.localeCompare(b.name);});
    function card(r,idx){if(!r)return {text:idx===1?'No second customer review found for this pull week.':'No customer review found for this pull week.',customer:'—',platform:'—',rep:'—'};var raw=r.raw||{};var txt=smClip(raw.msg||raw.message||'Customer review received. Open Customer Reviews for the full note.',155);return {text:txt,customer:raw.custName||raw.custId||'Customer',platform:r.platform||raw.type||'Review',rep:r.repDisplay||r.repName||raw.rep||'Unmatched'};}
    var withText=reviews.filter(function(r){return r.raw&&String(r.raw.msg||'').trim();});
    var pick=(withText.length?withText:reviews).slice(0,2);
    var reviewCards=[card(pick[0],0),card(pick[1],1)];
    return {reviews:reviews,paying:paying,reviewRows:reviewRows,reviewCards:reviewCards};}
  function smBlankRank(rank,positive){var idx=rank-1;return positive[idx]||null;}
  function slideData(){var pres=selectedPresentationWeek();var dataW=previousWeekFor(pres);var reps=(typeof activeReps==='function'?activeReps():(S.reps||[])).filter(function(r){return r&&r.name;});
    var weeklyRows=smWeeklyRows(reps,dataW),weeklyTotal=weeklyRows.reduce(function(s,r){return s+Number(r.revenue||0);},0);
    var daily=smDailyTeam(dataW);
    var dailyRepRows=smDailyRepRows(reps,dataW),dailyRepTotal=dailyRepRows.reduce(function(s,r){return s+Number(r.revenue||0);},0);
    var rows=weeklyRows,rankSource='weekly',total=weeklyTotal;
    if(weeklyTotal<=0&&dailyRepTotal>0){rows=dailyRepRows;rankSource='dailyRep';total=daily.total>0?daily.total:dailyRepTotal;}
    else if(weeklyTotal<=0&&daily.total>0){rows=[];rankSource='dailyTeam';total=daily.total;}
    else if(weeklyTotal>0&&daily.total>weeklyTotal*1.05){total=daily.total;}
    rows=(rows||[]).sort(function(a,b){return Number(b.revenue||0)-Number(a.revenue||0)||a.name.localeCompare(b.name);});
    var positive=smPositiveRows(rows);
    var hasSales=Number(total||0)>0;
    var hasRankings=positive.length>0;
    var qweeks=gwq(dataW.year,dataW.q)||[];var qGoal=reps.reduce(function(s,r){try{return s+Number(getGoal(r.name,dataW.year,dataW.q).rev||0);}catch(e){return s;}},0);var weeklyGoal=qweeks.length?qGoal/qweeks.length:0;
    var rv=smReviewData(dataW);
    var top1=smBlankRank(1,positive),top2=smBlankRank(2,positive),top3=smBlankRank(3,positive);
    var missingMsg='No prior-week sales data found';
    var summary=(document.getElementById('smSummaryText')||{}).value||(
      hasSales?('Last week closed at '+money(total)+' against a weekly goal of '+money(weeklyGoal)+'. '+(top1?('Top sales rep: '+top1.name+' at '+money(top1.revenue)+'.'):'Rep rankings were not available for this pull.')):
      ('No previous-week sales data was found for '+(dataW.label||('Wk '+dataW.num))+'. Check the selected meeting week, weekly sales entry, and daily sales calendar before presenting.')
    );
    var map={MEETING_WEEK:'Meeting week: '+(pres.label||('Wk '+pres.num))+' · pulling '+(dataW.label||('Wk '+dataW.num)),MEETING_SUBTITLE:'Triple Crown Products · Weekly sales meeting · Previous-week recap',SALES_1_NAME:top1?top1.name:missingMsg,SALES_1_AMOUNT:top1?money(top1.revenue):'',SALES_2_NAME:top2?top2.name:(hasRankings?'Only one rep with sales':'—'),SALES_2_AMOUNT:top2?money(top2.revenue):'',SALES_3_NAME:top3?top3.name:(positive.length===2?'Only two reps with sales':'—'),SALES_3_AMOUNT:top3?money(top3.revenue):'',SALES_3_RANK_NOTE:top3?('3rd place · '+money(top3.revenue)+' last week'):(hasSales?'Not enough rep-level sales for 3rd place':'No prior-week sales data found — check the Sales Slides preflight.'),TOTAL_SALES:hasSales?money(total):'No sales data found',TOTAL_GOAL:money(weeklyGoal),TOTAL_PACE_PERCENT:hasSales?(pct(total,weeklyGoal)+'%'):'—',TOTAL_SALES_CALLOUT:hasSales?(total>=weeklyGoal?'Beat the weekly pace':'Weekly sales recap'):'Check data before presenting',SMB_TOTAL:money(daily.smb||dailyRepTotal||0),CORP_TOTAL:money(daily.corp||0),SALES_SUMMARY_TEXT:summary,SALES_SNAPSHOT_IMAGE:'',REVIEW_WEEK:(dataW.label||('Wk '+dataW.num)),REVIEWS_TOTAL:String(rv.reviews.length||0),REVIEWS_PAYOUT_TOTAL:money(rv.paying.length*10)};
    var cards=rv.reviewCards||[];
    for(var h=0;h<2;h++){var rc=cards[h]||{text:'No customer review found for this pull week.',customer:'—',platform:'—',rep:'—'};map['REVIEW_'+(h+1)+'_TEXT']=rc.text;map['REVIEW_'+(h+1)+'_CUSTOMER']=rc.customer;map['REVIEW_'+(h+1)+'_PLATFORM']=rc.platform;map['REVIEW_'+(h+1)+'_REP']=rc.rep;}
    for(var i=0;i<6;i++){var pr=rv.reviewRows[i]||{name:'—',count:0,amount:0};map['PAYOUT_'+(i+1)+'_NAME']=pr.name;map['PAYOUT_'+(i+1)+'_COUNT']=pr.count?String(pr.count):'—';map['PAYOUT_'+(i+1)+'_AMOUNT']=pr.amount?money(pr.amount):'—';}
    map.PAYOUT_MORE_NOTE=rv.reviewRows.length>6?('+'+(rv.reviewRows.length-6)+' more reps earned review payouts'):(!rv.paying.length?'No Google/Trustpilot payouts found for this pull week.':'');
    for(var i=0;i<4;i++){var rr=rv.reviewRows[i]||{name:'—',count:0,amount:0};map['REVIEWS_'+(i+1)+'_NAME']=rr.name;map['REVIEWS_'+(i+1)+'_COUNT']=String(rr.count);map['REVIEWS_'+(i+1)+'_AMOUNT']=money(rr.amount);}
    for(var c=1;c<=3;c++){map['CUSTOM_0'+c+'_TITLE']=(document.getElementById('smCustomTitle'+c)||{}).value||'';map['CUSTOM_0'+c+'_TEXT']=(document.getElementById('smCustomText'+c)||{}).value||'';}
    var warnings=[];if(!hasSales)warnings.push('No previous-week sales total was found.');if(hasSales&&!hasRankings)warnings.push('Total sales found, but no rep-level ranking data was found.');if(hasRankings&&positive.length<3)warnings.push('Fewer than three reps had positive sales, so reveal slides will show an empty-state message.');if(!rv.reviews.length)warnings.push('No customer reviews found for the pull week.');if(rv.reviews.length&&!rv.paying.length)warnings.push('Reviews were found, but none qualified for the $10 Google/Trustpilot payout.');
    return {presentationWeek:pres,dataWeek:dataW,rows:rows,positiveRows:positive,total:total,weeklyGoal:weeklyGoal,daily:daily,reviews:rv.reviews,paying:rv.paying,reviewRows:rv.reviewRows,map:map,rankSource:rankSource,hasSales:hasSales,hasRankings:hasRankings,warnings:warnings};
  }
  function renderPreview(){var host=document.getElementById('smPreview');if(!host)return;var d=slideData();var top=(d.positiveRows&&d.positiveRows.length?d.positiveRows:d.rows).slice(0,3);var label=(d.dataWeek&&d.dataWeek.label)||'';var pres=(d.presentationWeek&&d.presentationWeek.label)||'';var ready=d.hasSales&&d.hasRankings;var html='<div class="sm-context"><div class="sm-kpi"><div class="sm-kpi-l">Presentation week</div><div class="sm-kpi-v">Wk '+esc(d.presentationWeek.num||'')+'</div><div class="sm-kpi-s">Selected: '+esc(pres)+'</div></div><div class="sm-kpi"><div class="sm-kpi-l">Deck pulls</div><div class="sm-kpi-v">Wk '+esc(d.dataWeek.num||'')+'</div><div class="sm-kpi-s">Previous week: '+esc(label)+'</div></div><div class="sm-kpi"><div class="sm-kpi-l">Sales pulled</div><div class="sm-kpi-v">'+money(d.total)+'</div><div class="sm-kpi-s">'+pct(d.total,d.weeklyGoal)+'% of '+money(d.weeklyGoal)+' weekly goal</div></div><div class="sm-kpi"><div class="sm-kpi-l">Reviews pulled</div><div class="sm-kpi-v">'+d.reviews.length+'</div><div class="sm-kpi-s">'+money(d.paying.length*10)+' payout</div></div></div>';
    html+='<div class="sm-preflight"><div class="sm-preflight-card '+(d.hasSales?'ok':'bad')+'"><div class="sm-preflight-dot">'+(d.hasSales?'✓':'!')+'</div><div><div class="sm-preflight-title">Previous-week sales</div><div class="sm-preflight-text">'+(d.hasSales?('Found '+money(d.total)+' from '+smSourceLabel(d.rankSource)+'.'):'No sales total found for the pull week. Check weekly entry or daily calendar.')+'</div></div></div><div class="sm-preflight-card '+(d.hasRankings?'ok':'warn')+'"><div class="sm-preflight-dot">'+(d.hasRankings?'✓':'!')+'</div><div><div class="sm-preflight-title">Rep rankings</div><div class="sm-preflight-text">'+(d.hasRankings?('Using '+smSourceLabel(d.rankSource)+' for the reveal slides.'):'No positive rep-level sales found; winner slides will not show fake $0 winners.')+'</div></div></div><div class="sm-preflight-card '+(d.reviews.length?'ok':'warn')+'"><div class="sm-preflight-dot">'+(d.reviews.length?'✓':'!')+'</div><div><div class="sm-preflight-title">Reviews</div><div class="sm-preflight-text">'+(d.reviews.length?(d.reviews.length+' reviews found; '+money(d.paying.length*10)+' payout.'):'No reviews found for the pull week.')+'</div></div></div><div class="sm-preflight-card '+(ready?'ok':'warn')+'"><div class="sm-preflight-dot">'+(ready?'✓':'!')+'</div><div><div class="sm-preflight-title">Deck readiness</div><div class="sm-preflight-text">'+(ready?'Ready to generate for the meeting.':'Generate is allowed, but the deck will carry clear no-data messages instead of fake winners.')+'</div></div></div></div>';
    var revCards=d.reviewCards||[];var payoutRows=(d.reviewRows||[]).slice(0,6);
    html+='<div class="sm-review-preview"><div class="sm-review-card"><div class="sm-review-title">Review slide preview</div>'+(revCards.length?revCards.slice(0,2).map(function(r,idx){return '<div style="margin-bottom:'+(idx===0?'10':'0')+'px"><div class="sm-review-quote">“'+esc(r.text||'')+'”</div><div class="sm-review-meta">'+esc(r.customer||'Customer')+' · '+esc(r.platform||'Review')+' · Rep: '+esc(r.rep||'—')+'</div></div>';}).join(''):'<div class="sm-review-meta">No reviews found for the pull week.</div>')+'</div><div class="sm-payout-card"><div class="sm-payout-title">Who got money this week</div>'+(payoutRows.length?payoutRows.map(function(r){return '<div class="sm-payout-row"><strong>'+esc(r.name)+'</strong><span>'+esc(r.count)+'</span><span>'+money(r.amount)+'</span></div>';}).join(''):'<div class="sm-review-meta">No Google/Trustpilot payouts found for the pull week.</div>')+'</div></div>';
    if(!d.hasSales){html+='<div class="sm-no-data-row"><strong>Heads up:</strong> this selected meeting week pulls '+esc(label)+', but the tracker did not find sales there. Pick a different meeting week or enter that prior week\'s data before presenting.</div>';}
    html+='<div class="sm-preview-list" style="margin-top:14px;">'+(top.length?top.map(function(r,i){return '<div class="sm-rank-row"><div class="sm-rank-num">'+(i+1)+'</div><div><div class="sm-rank-name">'+esc(r.name)+'</div><div class="sm-rank-sub">'+(r.orders||0)+' orders · '+(r.calls||0)+' calls · '+esc(smSourceLabel(d.rankSource))+'</div></div><div class="sm-rank-val">'+money(r.revenue)+'</div></div>';}).join(''):'<div class="sm-audit-note">No positive rep-level sales were found for the previous week. The deck will show a data-check message instead of ranking $0 reps.</div>')+'</div>';host.innerHTML=html;saveConfig();}
  function initSlidesPage(){var host=document.getElementById('slides-page');if(!host)return;if(!host.dataset.built){host.dataset.built='1';host.innerHTML='<div class="sm-hero"><div><div class="sm-eyebrow">Sales meeting generator</div><h1>Sales Meeting Slides</h1><p>Select the week you are holding the meeting. The deck automatically pulls the previous week\'s sales, customer reviews, and top-rep data so Monday meetings recap the completed week.</p></div><div class="sm-hero-actions"><button class="sm-btn" onclick="smUseTrackerWeek()">Match tracker week</button><button class="sm-btn primary" onclick="smGeneratePptx()">Generate PPTX</button></div></div><div class="sm-layout"><div class="sm-main-stack"><section class="sm-panel hot"><div class="sm-panel-head"><div><div class="sm-kicker">Meeting context</div><div class="sm-title">Select this week — pull last week</div><p class="sm-help">Example: choose Wk 28 for this week\'s meeting and the presentation will fill from Wk 27 results.</p></div><span class="sm-pill">Previous-week pull</span></div><div class="sm-controls"><div class="sm-field"><label>Year</label><select id="smYear" onchange="smPopulateWeeks();smRenderPreview();"></select></div><div class="sm-field"><label>Quarter</label><select id="smQuarter" onchange="smPopulateWeeks();smRenderPreview();"><option>Q1</option><option>Q2</option><option>Q3</option><option>Q4</option></select></div><div class="sm-field"><label>Meeting week</label><select id="smWeek" onchange="smRenderPreview();"></select></div><div><button class="sm-btn green" onclick="smGeneratePptx()" style="width:100%;min-height:40px;">Download deck</button></div></div><div id="smPreview"></div><div id="smStatus" class="sm-status"></div></section><section class="sm-panel"><div class="sm-panel-head"><div><div class="sm-kicker">Custom weekly slides</div><div class="sm-title">Add manager talking points</div><p class="sm-help">These feed the three custom slides at the back of the template. Images are inserted into the matching image placeholders when provided.</p></div><span class="sm-pill purple">3 optional slides</span></div><div class="sm-field" style="margin-bottom:13px;"><label>Sales summary text</label><textarea id="smSummaryText" placeholder="Optional weekly sales summary. Blank uses an auto-summary." oninput="smRenderPreview();"></textarea></div><div class="sm-custom-grid" id="smCustomGrid"></div></section></div><aside class="sm-side-stack"><section class="sm-panel"><div class="sm-panel-head"><div><div class="sm-kicker">Template</div><div class="sm-title">PowerPoint base file</div><p class="sm-help">The built-in adjusted template is already embedded. Upload a new template only when you redesign the PPTX placeholders.</p></div></div><div class="sm-template-box"><div class="sm-template-row"><input type="file" id="smTemplateFile" accept=".pptx" onchange="smUploadTemplate(this)"></div><div class="sm-audit-note" id="smTemplateStatus"></div><div class="sm-template-row"><button class="sm-btn" onclick="smResetTemplate()">Use built-in template</button></div></div></section><section class="sm-panel"><div class="sm-panel-head"><div><div class="sm-kicker">Default deck</div><div class="sm-title">Slides generated</div><p class="sm-help">These sections are filled from the previous week automatically. Reveal slides only show winners when positive rep-level sales are found.</p></div></div><div class="sm-slide-checks"><div class="sm-slide-check">Title / meeting week</div><div class="sm-slide-check">Customer reviews + payouts</div><div class="sm-slide-check">3rd place reveal</div><div class="sm-slide-check">2nd + 3rd reveal</div><div class="sm-slide-check">Top 3 sales reps</div><div class="sm-slide-check">Total sales snapshot</div><div class="sm-slide-check">Weekly sales summary</div><div class="sm-slide-check">Custom back slides</div></div></section><section class="sm-panel"><div class="sm-panel-head"><div><div class="sm-kicker">Workflow</div><div class="sm-title">Canva handoff</div></div></div><div class="sm-audit-note">Generate the PPTX here, then import that file into Canva if you want to reformat. The tracker owns the data pull; Canva owns the finishing polish.</div></section></aside></div>';}
    var y=document.getElementById('smYear');if(y&&!y.options.length)y.innerHTML=(typeof YEARS!=='undefined'?YEARS:[2026,2027,2028,2029,2030]).map(function(v){return '<option>'+v+'</option>';}).join('');var cfg=loadConfig();if(y)y.value=cfg.year||getYr();var q=document.getElementById('smQuarter');if(q)q.value=cfg.quarter||getQ();populateWeeks();var wk=document.getElementById('smWeek');if(wk)wk.value=cfg.week||String(getWN());var sum=document.getElementById('smSummaryText');if(sum&&cfg.summary)sum.value=cfg.summary;var grid=document.getElementById('smCustomGrid');if(grid&&!grid.dataset.built){grid.dataset.built='1';var custom=cfg.custom||[];var s='';for(var i=1;i<=3;i++){var c=custom[i-1]||{};s+='<div class="sm-custom-card"><h3>Custom slide 0'+i+'</h3><div class="sm-field"><label>Header</label><input id="smCustomTitle'+i+'" value="'+esc(c.title||'')+'" oninput="smRenderPreview();" placeholder="Slide headline"></div><div class="sm-field" style="margin-top:9px;"><label>Text</label><textarea id="smCustomText'+i+'" oninput="smRenderPreview();" placeholder="Talking points or weekly note">'+esc(c.text||'')+'</textarea></div><div class="sm-field" style="margin-top:9px;"><label>Image</label><input type="file" accept="image/*" onchange="smCustomImage('+i+',this)"><div class="sm-image-status" id="smImgStatus'+i+'">Optional image placeholder</div></div></div>';}grid.innerHTML=s;}
    var ts=document.getElementById('smTemplateStatus');if(ts)ts.textContent=templateName()+' ready. Placeholder deck fills when you generate.';renderPreview();}
  function b64ToUint8(b64){var bin=atob(b64);var len=bin.length;var bytes=new Uint8Array(len);for(var i=0;i<len;i++)bytes[i]=bin.charCodeAt(i);return bytes;}
  function dataUrlToUint8(dataUrl){var b64=String(dataUrl).split(',')[1]||'';return b64ToUint8(b64);}
  function imgExt(dataUrl){var m=String(dataUrl).match(/^data:image\/(png|jpeg|jpg|gif)/i);var e=m?m[1].toLowerCase():'png';return e==='jpeg'?'jpg':e;}
  async function addContentDefault(zip,ext,mime){var f=zip.file('[Content_Types].xml');if(!f)return;var ct=await f.async('string');if(ct.indexOf('Extension="'+ext+'"')<0){ct=ct.replace('</Types>','<Default Extension="'+ext+'" ContentType="'+mime+'"/></Types>');zip.file('[Content_Types].xml',ct);}}
  async function replaceImagePlaceholder(zip,placeholder,dataUrl,baseName){if(!dataUrl)return false;var slideFiles=Object.keys(zip.files).filter(function(n){return /^ppt\/slides\/slide\d+\.xml$/.test(n);});for(var si=0;si<slideFiles.length;si++){var path=slideFiles[si];var xml=await zip.file(path).async('string');if(xml.indexOf(placeholder)<0)continue;var parser=new DOMParser();var doc=parser.parseFromString(xml,'application/xml');var shapes=Array.prototype.slice.call(doc.getElementsByTagName('p:sp'));var target=null;shapes.some(function(sp){if((sp.textContent||'').indexOf(placeholder)>=0){target=sp;return true;}return false;});if(!target)continue;var off=target.getElementsByTagName('a:off')[0];var ext=target.getElementsByTagName('a:ext')[0];var x=off?off.getAttribute('x'):'914400',y=off?off.getAttribute('y'):'914400',cx=ext?ext.getAttribute('cx'):'4572000',cy=ext?ext.getAttribute('cy'):'2743200';var relPath=path.replace('ppt/slides/','ppt/slides/_rels/')+'.rels';var rels=zip.file(relPath)?await zip.file(relPath).async('string'):'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"></Relationships>';var max=0;rels.replace(/Id="rId(\d+)"/g,function(_,n){max=Math.max(max,parseInt(n,10));return _;});var rid='rId'+(max+1);var extn=imgExt(dataUrl);var mediaName=baseName+'.'+extn;var mediaPath='ppt/media/'+mediaName;zip.file(mediaPath,dataUrlToUint8(dataUrl));var type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/image';rels=rels.replace('</Relationships>','<Relationship Id="'+rid+'" Type="'+type+'" Target="../media/'+mediaName+'"/></Relationships>');zip.file(relPath,rels);await addContentDefault(zip,extn,extn==='jpg'?'image/jpeg':'image/'+extn);var pic='<p:pic xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><p:nvPicPr><p:cNvPr id="'+(9000+Math.floor(Math.random()*999))+'" name="'+baseName+'"/><p:cNvPicPr><a:picLocks noChangeAspect="1"/></p:cNvPicPr><p:nvPr/></p:nvPicPr><p:blipFill><a:blip r:embed="'+rid+'"/><a:stretch><a:fillRect/></a:stretch></p:blipFill><p:spPr><a:xfrm><a:off x="'+x+'" y="'+y+'"/><a:ext cx="'+cx+'" cy="'+cy+'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></p:spPr></p:pic>';var picDoc=parser.parseFromString(pic,'application/xml');target.parentNode.replaceChild(doc.importNode(picDoc.documentElement,true),target);zip.file(path,new XMLSerializer().serializeToString(doc));return true;}return false;}
  async function generatePptx(){try{setStatus('Preparing presentation...', '#8EDCFA');if(!window.JSZip)throw new Error('JSZip did not load. Check internet connection for the CDN script.');var d=slideData();if(!d.hasSales){var ok=confirm('No previous-week sales were found for '+((d.dataWeek&&d.dataWeek.label)||'the pull week')+'. The deck will generate with no-data messages instead of $0 winners. Generate anyway?');if(!ok){setStatus('Canceled — choose another week or enter prior-week sales first.', '#FFD27A');return;}}else if(!d.hasRankings){var ok2=confirm('Sales total was found, but no rep-level rankings were found. Generate deck without sales winners?');if(!ok2){setStatus('Canceled — add rep-level data first.', '#FFD27A');return;}}
    var zip=await JSZip.loadAsync(b64ToUint8(templateB64()));var imageKeys=['CUSTOM_01_IMAGE','CUSTOM_02_IMAGE','CUSTOM_03_IMAGE','SALES_SNAPSHOT_IMAGE'];for(var i=1;i<=3;i++){if(customImages[i])await replaceImagePlaceholder(zip,'{{CUSTOM_0'+i+'_IMAGE}}',customImages[i],'custom_0'+i+'_image');}var files=Object.keys(zip.files).filter(function(n){return /^ppt\/slides\/slide\d+\.xml$/.test(n);});for(var f=0;f<files.length;f++){var name=files[f];var xml=await zip.file(name).async('string');Object.keys(d.map).forEach(function(k){if(imageKeys.indexOf(k)>=0)return;var token='{{'+k+'}}';xml=xml.split(token).join(xmlEsc(d.map[k]));});imageKeys.forEach(function(k){xml=xml.split('{{'+k+'}}').join('');});zip.file(name,xml);}var blob=await zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.presentationml.presentation'});var a=document.createElement('a');var datePart=(d.dataWeek&&d.dataWeek.year?d.dataWeek.year:'')+'_Wk'+(d.dataWeek&&d.dataWeek.num?d.dataWeek.num:'');a.href=URL.createObjectURL(blob);a.download='Sales_Meeting_'+datePart+'.pptx';document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},1200);setStatus('Downloaded deck for '+((d.dataWeek&&d.dataWeek.label)||'previous week')+'.', '#A7FFC0');}catch(err){console.error(err);setStatus('Generate failed: '+(err&&err.message?err.message:err), '#FFB3C8');alert('Generate failed: '+(err&&err.message?err.message:err));}}
  window.initSlidesPage=initSlidesPage;window.smPopulateWeeks=populateWeeks;window.smRenderPreview=renderPreview;window.smUseTrackerWeek=function(){initSlidesPage();var y=document.getElementById('smYear'),q=document.getElementById('smQuarter'),w=document.getElementById('smWeek');if(y)y.value=getYr();if(q)q.value=getQ();populateWeeks();if(w)w.value=String(getWN());renderPreview();};window.smGeneratePptx=generatePptx;window.smUploadTemplate=function(input){var file=input&&input.files&&input.files[0];if(!file)return;var reader=new FileReader();reader.onload=function(e){var dataUrl=String(e.target.result||'');var b64=dataUrl.split(',')[1]||'';try{localStorage.setItem(TEMPLATE_STORE,b64);localStorage.setItem(TEMPLATE_NAME_STORE,file.name);}catch(err){alert('Could not store template in browser storage. The file may be too large.');return;}var ts=document.getElementById('smTemplateStatus');if(ts)ts.textContent=file.name+' stored as the active template.';setStatus('Template updated.', '#A7FFC0');};reader.readAsDataURL(file);};window.smResetTemplate=function(){try{localStorage.removeItem(TEMPLATE_STORE);localStorage.removeItem(TEMPLATE_NAME_STORE);}catch(e){}var ts=document.getElementById('smTemplateStatus');if(ts)ts.textContent='Built-in Sales Meeting template ready.';setStatus('Using built-in template.', '#A7FFC0');};window.smCustomImage=function(i,input){var f=input&&input.files&&input.files[0];var st=document.getElementById('smImgStatus'+i);if(!f){delete customImages[i];if(st)st.textContent='Optional image placeholder';return;}var r=new FileReader();r.onload=function(e){customImages[i]=e.target.result;if(st)st.textContent='Image ready: '+f.name;};r.readAsDataURL(f);};
  document.addEventListener('DOMContentLoaded',function(){try{if(document.getElementById('pg-slides')&&document.getElementById('pg-slides').classList.contains('active'))initSlidesPage();}catch(e){}});
})();
